function addDeliveryUomFields() { document.querySelectorAll('#delivery-lines tbody tr').forEach(row => { const input = row.querySelector('input[name="delivered_qty[]"]'); if (!input || input.dataset.uomReady) return; input.dataset.uomReady = '1'; const select = document.createElement('select'); select.name = 'uom_id[]'; select.className = 'form-select form-select-sm mb-1'; select.innerHTML = '<option value="">Stock UOM</option>' + deliveryUnits.map(unit => `<option value="${unit.id}">${unit.name}</option>`).join(''); input.parentElement.prepend(select); }); }
